# filename: extract_with_pdfplumber.py
import pdfplumber
import pandas as pd

pdf_path = "/Data2/v-weilinjin/workshop/AttributeBench/benchmarks/GAIA/2023/validation/67e8878b-5cef-4375-804e-e6291fdbe78a.pdf"

rows = []
current_type = None
possible_types = {"Hotels", "Motels", "Villas", "Inns", "Guesthouses", "Resorts", "Cottages", "B&Bs"}

with pdfplumber.open(pdf_path) as pdf:
    for page in pdf.pages:
        # Attempt to extract tables
        tables = page.extract_tables()
        for table in tables:
            # Convert to DataFrame for easier handling
            df = pd.DataFrame(table)
            # Try to infer headers: look for a row containing 'Name' and 'Rating'
            header_idx = None
            for i in range(len(df)):
                row_vals = [str(x) for x in df.iloc[i].tolist()]
                if any("Name" in v for v in row_vals) and any("Rating" in v for v in row_vals):
                    header_idx = i
                    break
            if header_idx is None:
                # Process rows as-is and look for section headers
                for i in range(len(df)):
                    name = str(df.iloc[i,0]).strip()
                    # Section header detection
                    if name in possible_types:
                        current_type = name
                        continue
                    # Rating detection (assume rating appears in second column if numeric)
                    rating_val = None
                    for col in range(df.shape[1]):
                        cell = str(df.iloc[i,col]).strip()
                        try:
                            val = float(cell)
                            if 0.0 <= val <= 5.0:
                                rating_val = val
                                break
                        except:
                            pass
                    if current_type and name and rating_val is not None and name not in possible_types:
                        rows.append({"Name": name, "Type": current_type, "Rating": rating_val})
            else:
                # Use the detected header row to define columns
                cols = [str(x).strip() for x in df.iloc[header_idx].tolist()]
                sub = df.iloc[header_idx+1:].reset_index(drop=True)
                # Identify column indices for Name and Rating
                name_col = None
                rating_col = None
                for ci, cv in enumerate(cols):
                    if "Name" in cv:
                        name_col = ci
                    if "Rating" in cv:
                        rating_col = ci
                for i in range(len(sub)):
                    name = str(sub.iloc[i, name_col]).strip() if name_col is not None else str(sub.iloc[i,0]).strip()
                    # Section headers may appear in Name column
                    if name in possible_types:
                        current_type = name
                        continue
                    # Rating
                    rating_val = None
                    if rating_col is not None:
                        cell = str(sub.iloc[i, rating_col]).strip()
                        try:
                            val = float(cell)
                            if 0.0 <= val <= 5.0:
                                rating_val = val
                        except:
                            rating_val = None
                    else:
                        # Fallback: search entire row for a numeric rating
                        for col in range(sub.shape[1]):
                            cell = str(sub.iloc[i,col]).strip()
                            try:
                                val = float(cell)
                                if 0.0 <= val <= 5.0:
                                    rating_val = val
                                    break
                            except:
                                pass
                    if current_type and name and rating_val is not None and name not in possible_types:
                        rows.append({"Name": name, "Type": current_type, "Rating": rating_val})

# Create DataFrame
parsed_df = pd.DataFrame(rows)
print(parsed_df.head(12))
print(parsed_df['Type'].value_counts())
